mapper.insert:
/*
    SQL ID : AsmtFdbkDAO.asmtFdbkBulkRegist
    설  명 : 과제 피드백 일괄 등록
*/
INSERT ALL

    INTO TB_LMS_ASMT_FDBK
    (
          ASMT_FDBK_ID
        , ASMT_ID
        , USER_ID
        , TEAM_ID
        , FDBK_CTS
        , DELYN
        , PUSH_ALIMYN
        , RGTR_ID
        , REG_DTTM
    )
    VALUES
    (
          #{item.asmtFdbkId}
        , #{item.asmtId}
        , #{item.userId}
        , #{item.teamId}
        , #{item.fdbkCts}
        , 'N'
        , 'Y'
        , #{item.rgtrId}
        , FN_DTTM()
    )

SELECT 1 FROM DUAL

mapper.select:
/*
    SQL ID : AsmtFdbkDAO.asmtFdbkList
    설  명 : 과제 피드백 목록 조회
*/
SELECT FDBK.*
     , FN_REF_FILE_CNT(FDBK.ASMT_FDBK_ID) AS FILE_CNT
FROM TB_LMS_ASMT_FDBK FDBK
WHERE DELYN = 'N'
  AND ASMT_ID = #{asmtId}
    AND USER_ID = #{userId}

mapper.update:
/*
  SQL ID : AsmtFdbkDAO.asmtFdbkDelete
  설  명 : 과제 피드백 삭제
*/
UPDATE TB_LMS_ASMT_FDBK
SET
    DELYN = 'Y'
    , MDFR_ID = #{mdfrId}
    , MOD_DTTM = FN_DTTM()
WHERE ASMT_FDBK_ID = #{asmtFdbkId}
